-- PawSpace employee + payroll + GST UAT seed (generated). Safe to re-run.
CREATE TABLE IF NOT EXISTS app_users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL, role_code TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS employees (id TEXT PRIMARY KEY,user_email TEXT UNIQUE,employee_code TEXT NOT NULL UNIQUE,display_name TEXT NOT NULL,work_email TEXT NOT NULL UNIQUE,phone TEXT,employment_status TEXT NOT NULL DEFAULT 'active',joined_at INTEGER,ended_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS salary_structure_versions (id TEXT PRIMARY KEY,structure_code TEXT NOT NULL,version INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'draft',effective_from INTEGER NOT NULL,effective_until INTEGER,currency TEXT NOT NULL DEFAULT 'INR',components_json TEXT NOT NULL,approval_reference TEXT,created_by TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(structure_code,version));
CREATE TABLE IF NOT EXISTS employee_compensation_assignments (id TEXT PRIMARY KEY,employee_id TEXT NOT NULL,structure_id TEXT NOT NULL,effective_from INTEGER NOT NULL,effective_until INTEGER,reason TEXT NOT NULL,actor_id TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS payroll_runs (id TEXT PRIMARY KEY,idempotency_key TEXT NOT NULL UNIQUE,period_start INTEGER NOT NULL,period_end INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'draft',input_snapshot_json TEXT NOT NULL,created_by TEXT NOT NULL,created_at INTEGER NOT NULL,reviewed_by TEXT,reviewed_at INTEGER,approved_by TEXT,approved_at INTEGER,payment_prepared_at INTEGER);
CREATE TABLE IF NOT EXISTS employee_payroll_results (id TEXT PRIMARY KEY,run_id TEXT NOT NULL,employee_id TEXT NOT NULL,structure_id TEXT NOT NULL,gross_earnings REAL NOT NULL,total_deductions REAL NOT NULL,reimbursements REAL NOT NULL,employer_cost REAL NOT NULL,net_pay REAL NOT NULL,source_snapshot_json TEXT NOT NULL,UNIQUE(run_id,employee_id));
CREATE TABLE IF NOT EXISTS payroll_result_lines (id TEXT PRIMARY KEY,result_id TEXT NOT NULL,component_code TEXT NOT NULL,label TEXT NOT NULL,kind TEXT NOT NULL,amount REAL NOT NULL,source_type TEXT NOT NULL,source_reference TEXT,policy_version TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS payslips (id TEXT PRIMARY KEY,run_id TEXT NOT NULL,employee_id TEXT NOT NULL,result_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'available_uat',created_at INTEGER NOT NULL,UNIQUE(run_id,employee_id));
CREATE TABLE IF NOT EXISTS sales_employee_base (id TEXT PRIMARY KEY,employee_id TEXT NOT NULL,base_vertical TEXT NOT NULL,effective_from TEXT NOT NULL,effective_until TEXT,reason TEXT NOT NULL,actor_id TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sales_attributed_bookings (id TEXT PRIMARY KEY,booking_id TEXT NOT NULL UNIQUE,employee_id TEXT NOT NULL,recorded_by TEXT NOT NULL,recorded_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS canonical_bookings (id TEXT PRIMARY KEY,idempotency_key TEXT NOT NULL UNIQUE,customer_id TEXT NOT NULL,pet_ids_json TEXT NOT NULL,source_pet_ids_json TEXT NOT NULL,city_id TEXT NOT NULL,zone_id TEXT NOT NULL,service_code TEXT NOT NULL,package_code TEXT NOT NULL,package_name TEXT NOT NULL,schedule_group_id TEXT NOT NULL UNIQUE,provider_id TEXT NOT NULL,scheduled_start TEXT NOT NULL,scheduled_end TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'confirmed',channel TEXT NOT NULL DEFAULT 'customer_app',total_amount REAL NOT NULL,currency TEXT NOT NULL DEFAULT 'INR',pricing_json TEXT NOT NULL DEFAULT '{}',created_by TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS groomer_incentive_brackets (id TEXT PRIMARY KEY,head_groomer_id TEXT NOT NULL,bracket TEXT NOT NULL,helper_id TEXT,effective_from TEXT NOT NULL,effective_until TEXT,reason TEXT NOT NULL,actor_id TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS groomer_monthly_targets (id TEXT PRIMARY KEY,head_groomer_id TEXT NOT NULL,month_start TEXT NOT NULL,target_amount REAL NOT NULL,reason TEXT NOT NULL,actor_id TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(head_groomer_id,month_start));
CREATE TABLE IF NOT EXISTS trainer_meet_greet_conversions (id TEXT PRIMARY KEY,trainer_id TEXT NOT NULL,meet_greet_booking_id TEXT NOT NULL UNIQUE,converted_booking_id TEXT NOT NULL UNIQUE,converted_order_value REAL NOT NULL,incentive_amount REAL NOT NULL,recorded_by TEXT NOT NULL,recorded_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS finance_entities (id TEXT PRIMARY KEY,legal_name TEXT NOT NULL,country_code TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',approved_by TEXT,approved_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS tax_registrations (id TEXT PRIMARY KEY,entity_id TEXT NOT NULL,jurisdiction TEXT NOT NULL,registration_type TEXT NOT NULL,registration_reference TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',effective_from TEXT,effective_to TEXT,approved_by TEXT,approved_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS tax_policy_versions (id TEXT PRIMARY KEY,entity_id TEXT NOT NULL,version INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'draft',effective_from TEXT NOT NULL,effective_to TEXT,policy_json TEXT NOT NULL,approval_reference TEXT,approved_by TEXT,approved_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(entity_id,version));
CREATE TABLE IF NOT EXISTS tax_classifications (id TEXT PRIMARY KEY,policy_id TEXT NOT NULL,service_code TEXT NOT NULL,classification_code TEXT NOT NULL,tax_component_json TEXT NOT NULL,place_of_supply_rule TEXT NOT NULL,input_tax_rule TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(policy_id,service_code));
CREATE TABLE IF NOT EXISTS finance_invoices (id TEXT PRIMARY KEY,invoice_number TEXT NOT NULL UNIQUE,entity_id TEXT NOT NULL,customer_id TEXT NOT NULL,source_type TEXT NOT NULL,source_id TEXT NOT NULL,source_event_key TEXT NOT NULL UNIQUE,policy_id TEXT NOT NULL,registration_id TEXT NOT NULL,issue_date TEXT NOT NULL,currency TEXT NOT NULL,subtotal REAL NOT NULL,tax_total REAL NOT NULL,total REAL NOT NULL,status TEXT NOT NULL DEFAULT 'issued',tax_snapshot_json TEXT NOT NULL,document_reference TEXT,created_by TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(source_type,source_id));
CREATE TABLE IF NOT EXISTS finance_invoice_lines (id TEXT PRIMARY KEY,invoice_id TEXT NOT NULL,line_key TEXT NOT NULL,description TEXT NOT NULL,service_code TEXT NOT NULL,taxable_amount REAL NOT NULL,tax_amount REAL NOT NULL,tax_snapshot_json TEXT NOT NULL,UNIQUE(invoice_id,line_key));
